initJs:
function(container, apiUrl, tables) {
  let currentStoreId = '';
  let currentOrderDate = '';
  let currentProducts = [];
  let stores = [];
  let categories = [];
  let demandForecasts = [];
  let products = [];

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;
  currentOrderDate = today;

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗マスタ読み込み
      const storeData = await window.aivicApi.list(1);
      if (storeData) {
        stores = storeData.filter(s => s.有効フラグ);
        renderStoreOptions();
      }

      // 商品マスタ読み込み
      const productData = await window.aivicApi.list(2);
      if (productData) {
        products = productData.filter(p => p.有効フラグ && p.AI予測対象フラグ);
        renderCategoryOptions();
      }

      // 需要予測結果読み込み
      const forecastData = await window.aivicApi.list(8);
      if (forecastData) {
        demandForecasts = forecastData;
      }
    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
    }
  }

  // 店舗選択肢を描画
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    stores.forEach(store => {
      storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
    });
  }

  // カテゴリ選択肢を描画
  function renderCategoryOptions() {
    const categorySelect = container.querySelector('#category-filter');
    categorySelect.innerHTML = '<option value="">全てのカテゴリ</option>';

    // 商品からカテゴリを抽出（重複除去）
    const uniqueCategories = [...new Set(products.map(p => p.商品カテゴリID))];
    uniqueCategories.forEach(categoryId => {
      if (categoryId) {
        categorySelect.innerHTML += `<option value="${categoryId}">カテゴリ${categoryId.slice(-8)}</option>`;
      }
    });
  }

  // 商品一覧を描画
  function renderProducts() {
    const tbody = container.querySelector('#order-table-body');

    if (!currentStoreId) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--text-muted); padding: 40px;">店舗を選択してください</td></tr>';
      updateExecuteButtons();
      return;
    }

    if (currentProducts.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--text-muted); padding: 40px;">データがありません</td></tr>';
      updateExecuteButtons();
      return;
    }

    tbody.innerHTML = currentProducts.map(product => {
      const forecast = demandForecasts.find(f => 
        f.店舗ID === currentStoreId && 
        f.商品ID === product.商品ID &&
        f.予測対象日 === currentOrderDate
      );

      const predictedDemand = forecast ? forecast.予測数量 : 0;
      const recommendedOrder = forecast ? forecast.推奨発注数量 : 0;
      const currentStock = Math.floor(Math.random() * 50); // 仮の在庫数

      return `
        <tr data-product-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" data-product-id="${product.商品ID}" /></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td style="text-align: right;">${predictedDemand}</td>
          <td style="text-align: right;">${recommendedOrder}</td>
          <td style="text-align: right;">${currentStock}</td>
          <td>
            <input type="number" 
                   class="input order-quantity" 
                   data-product-id="${product.商品ID}"
                   data-unit-price="${product.単価 || 0}"
                   value="${recommendedOrder}" 
                   min="0" 
                   step="1"
                   style="width: 80px;" />
          </td>
          <td style="text-align: right;">${(product.単価 || 0).toLocaleString()}円</td>
          <td style="text-align: right;">
            <span class="order-amount" data-product-id="${product.商品ID}">
              ${((product.単価 || 0) * recommendedOrder).toLocaleString()}円
            </span>
          </td>
        </tr>
      `;
    }).join('');

    updateTotalAmount();
    updateExecuteButtons();
  }

  // 商品データを更新
  async function updateProductList() {
    if (!currentStoreId) {
      currentProducts = [];
      renderProducts();
      return;
    }

    const categoryFilter = container.querySelector('#category-filter').value;

    // カテゴリフィルターを適用
    let filteredProducts = products;
    if (categoryFilter) {
      filteredProducts = products.filter(p => p.商品カテゴリID === categoryFilter);
    }

    currentProducts = filteredProducts;
    renderProducts();
  }

  // 合計金額を更新
  function updateTotalAmount() {
    let total = 0;
    container.querySelectorAll('.order-quantity').forEach(input => {
      const quantity = parseInt(input.value) || 0;
      const unitPrice = parseInt(input.dataset.unitPrice) || 0;
      total += quantity * unitPrice;

      // 個別金額も更新
      const amountSpan = container.querySelector(`.order-amount[data-product-id="${input.dataset.productId}"]`);
      if (amountSpan) {
        amountSpan.textContent = (quantity * unitPrice).toLocaleString() + '円';
      }
    });

    container.querySelector('#total-amount').textContent = total.toLocaleString();
  }

  // 発注実行ボタンの状態を更新
  function updateExecuteButtons() {
    const executeBtn = container.querySelector('#btn-execute-order');
    const executeSelectedBtn = container.querySelector('#btn-execute-selected');
    const hasProducts = currentProducts.length > 0 && currentStoreId;
    const hasSelectedProducts = container.querySelectorAll('.product-checkbox:checked').length > 0;

    executeBtn.disabled = !hasProducts;
    executeSelectedBtn.disabled = !hasSelectedProducts;
  }

  // バリデーション
  function validateOrderData(selectedOnly = false) {
    const errors = [];

    if (!currentStoreId) {
      errors.push('店舗を選択してください');
    }

    if (!currentOrderDate) {
      errors.push('発注日付を選択してください');
    } else if (new Date(currentOrderDate) < new Date(today)) {
      errors.push('発注日付は本日以降の日付を選択してください');
    }

    const quantityInputs = selectedOnly ? 
      container.querySelectorAll('.product-checkbox:checked').length > 0 ?
        Array.from(container.querySelectorAll('.order-quantity')).filter(input => {
          const checkbox = container.querySelector(`.product-checkbox[data-product-id="${input.dataset.productId}"]`);
          return checkbox && checkbox.checked;
        }) :
        [] :
      container.querySelectorAll('.order-quantity');

    if (quantityInputs.length === 0) {
      errors.push(selectedOnly ? '発注する商品を選択してください' : '発注対象商品がありません');
    }

    quantityInputs.forEach(input => {
      const value = input.value.trim();
      const quantity = parseFloat(value);

      if (value === '') {
        errors.push('発注数量を入力してください');
      } else if (isNaN(quantity)) {
        errors.push('発注数量は数値を入力してください');
      } else if (quantity < 0) {
        errors.push('発注数量は正の値を入力してください');
      } else if (quantity === 0) {
        errors.push('発注数量は1以上の値を入力してください');
      } else if (!Number.isInteger(quantity)) {
        errors.push('発注数量は整数を入力してください');
      }
    });

    return errors;
  }

  // 発注確認ダイアログを表示
  function showOrderConfirmDialog(selectedOnly = false) {
    const errors = validateOrderData(selectedOnly);
    if (errors.length > 0) {
      alert(errors.join('\n'));
      return;
    }

    const dialog = container.querySelector('#order-confirm-dialog');
    const content = container.querySelector('#confirm-content');

    const quantityInputs = selectedOnly ? 
      Array.from(container.querySelectorAll('.order-quantity')).filter(input => {
        const checkbox = container.querySelector(`.product-checkbox[data-product-id="${input.dataset.productId}"]`);
        return checkbox && checkbox.checked && (parseInt(input.value) || 0) > 0;
      }) :
      Array.from(container.querySelectorAll('.order-quantity')).filter(input => (parseInt(input.value) || 0) > 0);

    let totalAmount = 0;
    const orderItems = quantityInputs.map(input => {
      const productId = input.dataset.productId;
      const quantity = parseInt(input.value) || 0;
      const unitPrice = parseInt(input.dataset.unitPrice) || 0;
      const amount = quantity * unitPrice;
      totalAmount += amount;

      const product = currentProducts.find(p => p.商品ID === productId);
      return {
        productId,
        productCode: product?.商品コード || '',
        productName: product?.商品名|| '',
        quantity,
        unitPrice,
        amount
      };
    });

    const storeName = stores.find(s => s.店舗ID === currentStoreId)?.店舗名 || '';

    content.innerHTML = `
      <div style="margin-bottom: 20px;">
        <p><strong>店舗:</strong> ${storeName}</p>
        <p><strong>発注日付:</strong> ${currentOrderDate}</p>
      </div>
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>商品コード</th>
              <th>商品名</th>
              <th>数量</th>
              <th>単価</th>
              <th>金額</th>
            </tr>
          </thead>
          <tbody>
            ${orderItems.map(item => `
              <tr>
                <td>${item.productCode}</td>
                <td>${item.productName}</td>
                <td style="text-align: right;">${item.quantity}</td>
                <td style="text-align: right;">${item.unitPrice.toLocaleString()}円</td>
                <td style="text-align: right;">${item.amount.toLocaleString()}円</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
      <div style="text-align: right; margin-top: 10px; font-weight: bold;">
        合計: ${totalAmount.toLocaleString()}円
      </div>
    `;

    dialog.classList.remove('hidden');

    // 確認ダイアログのボタンイベント
    const confirmBtn = container.querySelector('#btn-confirm-execute');
    const cancelBtn = container.querySelector('#btn-confirm-cancel');

    confirmBtn.onclick = () => executeOrder(orderItems);
    cancelBtn.onclick = () => dialog.classList.add('hidden');
  }

  // 発注実行
  async function executeOrder(orderItems) {
    try {
      const dialog = container.querySelector('#order-confirm-dialog');
      dialog.classList.add('hidden');

      // 各商品の発注データを保存
      for (const item of orderItems) {
        const orderData = {
          店舗ID: currentStoreId,
          商品ID: item.productId,
          発注日: currentOrderDate,
          納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0], // 3日後
          発注数量: item.quantity,
          発注単価: item.unitPrice,
          発注金額: item.amount,
          発注方法: 'AI推奨採用',
          発注ステータス: '発注済',
          仕入先ID: 'supplier-001',
          自動発注フラグ: false,
          作成者ID: 'current-user',
          更新者ID: 'current-user'
        };

        await window.aivicApi.save(9, orderData);
      }

      alert('発注が正常に実行されました');

      // 発注数量をリセット
      container.querySelectorAll('.order-quantity').forEach(input => {
        input.value = '0';
      });
      container.querySelectorAll('.product-checkbox').forEach(checkbox => {
        checkbox.checked = false;
      });
      container.querySelector('#select-all').checked = false;

      updateTotalAmount();
      updateExecuteButtons();

    } catch (error) {
      console.error('発注実行エラー:', error);
      alert('発注実行中にエラーが発生しました');
    }
  }

  // イベントリスナー設定

  // 店舗選択
  container.querySelector('#store-select').addEventListener('change', (e) => {
    currentStoreId = e.target.value;
    updateProductList();
  });

  // 発注日付選択
  container.querySelector('#order-date').addEventListener('change', (e) => {
    currentOrderDate = e.target.value;
    updateProductList();
  });

  // カテゴリフィルター
  container.querySelector('#category-filter').addEventListener('change', () => {
    updateProductList();
  });

  // 表示更新ボタン
  container.querySelector('#btn-search').addEventListener('click', () => {
    updateProductList();
  });

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.product-checkbox');
    checkboxes.forEach(checkbox => {
      checkbox.checked = e.target.checked;
    });
    updateExecuteButtons();
  });

  // 商品チェックボックス
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('product-checkbox')) {
      updateExecuteButtons();

      // 全選択チェックボックスの状態を更新
      const allCheckboxes = container.querySelectorAll('.product-checkbox');
      const checkedCheckboxes = container.querySelectorAll('.product-checkbox:checked');
      const selectAllCheckbox = container.querySelector('#select-all');

      if (checkedCheckboxes.length === 0) {
        selectAllCheckbox.indeterminate = false;
        selectAllCheckbox.checked = false;
      } else if (checkedCheckboxes.length === allCheckboxes.length) {
        selectAllCheckbox.indeterminate = false;
        selectAllCheckbox.checked = true;
      } else {
        selectAllCheckbox.indeterminate = true;
      }
    }
  });

  // 発注数量入力
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('order-quantity')) {
      updateTotalAmount();
    }
  });

  // 発注実行ボタン
  container.querySelector('#btn-execute-order').addEventListener('click', () => {
    showOrderConfirmDialog(false);
  });

  // 選択商品発注実行ボタン
  container.querySelector('#btn-execute-selected').addEventListener('click', () => {
    showOrderConfirmDialog(true);
  });

  // 初期データ読み込み実行
  loadInitialData();
}
